import React from 'react';
import { useIntl } from 'react-intl';
import { UseSortByColumnProps } from 'react-table';
import styled from 'styled-components';

import {
  ArrowSmallDownIcon,
  SorterSmallDoubleIcon,
} from '@dynatrace/strato-icons';

//#region  StyledComponents
const StyledSortableArrow = /* @__PURE__ */ styled('span')({
  display: 'inline-block',

  '.arrow-toggle': {
    svg: {
      transition: 'transform 250ms ease-out',
    },
  },

  '.arrow-toggle--up': {
    svg: {
      transform: 'rotate(180deg)',
    },
  },

  svg: {
    display: 'flex',
    fill: 'currentColor',
  },
});

//#endregion

/** Helper component that will render the arrows for sorting and sorted direction. */
export const SortableArrow = ({
  isSorted,
  isSortedDesc = false,
}: Pick<
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  UseSortByColumnProps<any>,
  'isSorted' | 'isSortedDesc'
>) => {
  const intl = useIntl();
  const ariaLabel = intl.formatMessage({
    defaultMessage: 'sortable',
    id: 'Jmwdec/DsgVwQGYI',
    description:
      'Aria-label for sortable columns that are not yet sorted in any direction.',
  });

  return (
    <StyledSortableArrow
      className="strato-table-sort-icon"
      data-testid="table-sort-icon"
      {...(!isSorted && { 'aria-label': ariaLabel })}
    >
      {isSorted ? (
        <span
          className={`arrow-toggle ${isSortedDesc ? '' : 'arrow-toggle--up'}`}
        >
          {<ArrowSmallDownIcon />}
        </span>
      ) : (
        <SorterSmallDoubleIcon />
      )}
    </StyledSortableArrow>
  );
};
